	st.current++
	st.versions[st.current] = snapshot
	st.appendAuditLocked(org, AuditPolicyChange, &PolicyChange{
		Version:       st.current,
		Policies:      snapshot,
		SourceVersion: sourceVersion,
		RolledBack:    rolledBack,
	}, nil)
	return st.current
}

